export const ASSEMBLY_SKETCH = "# CWA integration sketch — not runnable or a reference implementation.\n# Implement these application-owned helpers; producers run before assembly.\ndef prepare_request(req):\n    # Keep each batch whole: its items and exclusions stay bound to the producer identity\n    # your application authenticated. Never flatten items away from that identity or\n    # read identity from item.source.\n    batches = [bind_identity(authenticate(producer), producer.run(req)) for producer in producers_for(req)]\n    snapshot = freeze_snapshot(\n        batches=batches,\n        capabilities=capability_grant(req),  # Allow-list result for this route and user.\n        conflicts=declared_conflict_groups(req),  # schema/conflict_group.schema.json\n        scope=request_scope(req),\n        assembly_time=req.assembly_time,\n        route_policy=load_versioned_policy(req.route),\n        profile=load_profile('policy-first-chat/v1'),\n        tokenizer=req.tokenizer,\n        renderer=req.renderer,\n        budget=req.budget,  # input is already net of reserved_output.\n    )\n    return assemble_snapshot(snapshot)\n\n\ndef assemble_snapshot(snapshot):\n    # No model calls, external reads, or ambient clock reads from this point.\n    admitted = admit(snapshot)\n    resolved = resolve_declared_conflicts(admitted, snapshot)\n    fitted = fit_with_rendered_token_counts(resolved, snapshot)\n    if fitted.refused:\n        return refused_result(fitted.reason, snapshot)  # No payload; trace.result = null.\n    payload = render_profile(fitted, snapshot)\n    return result_with_trace_and_sha256(payload, fitted, snapshot)\n";
